   * output ports.  Use named arguments to check subsets of the output ports.
   * @param qualified_outcome method that will be called with the value of the outgoing data
   *        port 'qualified_outcome'.
   */
  def check_concrete_output(qualified_outcome: Factory_Dispatch_Coordinator.QualifiedOutcome.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val qualified_outcomeValue: Factory_Dispatch_Coordinator.QualifiedOutcome.Type = get_qualified_outcome().get
    if(!qualified_outcome(qualified_outcomeValue)) {
