  def get_qualified_outcome(): Option[Factory_Dispatch_Coordinator.QualifiedOutcome.Type] = {
    val value: Option[Factory_Dispatch_Coordinator.QualifiedOutcome.Type] = get_qualified_outcome_payload() match {
